#!/usr/bin/env python3
# patch-158-G1: small fixes - progress bar, sale banners, confirm modals
"""
Three small fixes after first round of user testing:

1. Progress bar fill line overshoots the current step. Was using
   a 0-100 percent var multiplied against the bar full width,
   ignoring the 12px padding on each side. Legacy uses a 0..1
   fraction multiplied against (100% - 24px). Now matches.

2. Sale callout banner ("Ready for checkout - $X", "Paid in full",
   "Customer overpaid") wasn't being rendered in the multi-asset
   view. Ported from legacy: shows above the status pipeline,
   with the same amber/green/amber color scheme and an Open in
   Register link when a draft sale is parked.

3. Backward status transitions and the Reopen button were using
   native browser confirm() dialogs. Legacy uses IntakeConfirm
   (themed promise-based modal). Now matches, with native fallback
   if IntakeConfirm isn't loaded.

Single-file view patch. No controller / model / schema changes.

Next: G2 (parts per-asset) + G3 (work order per-asset). Both need
schema migrations and larger UI restructures.
"""
